      "id": "r2",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "तृष्णाधिकारमाह ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "विवेकव्याकोशे विकसति शमे शाम्यति तृषा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "परिष्वङ्गे तुङ्गे प्रसरतितरां सा परिणतिः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "जराजीर्णैश्वर्यग्रसनगहनाक्षेपकॄपण-",
          "end": "line"
        },
        {
          "n": 4,
          "text": "स्तृषापात्रं यस्यां भवति मरुतामप्यधिपतिः ॥ १७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "मदनविडम्बनमाह ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "कृशः काणः खञ्जः श्रवणरहितः पुच्छविकलो",
          "end": "line"
        },
        {
          "n": 2,
          "text": "व्रणी पूतिक्लिन्नः कृमिकुलशतैरावृततनुः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "क्षुधाक्षामो जीर्णः पिठरजकपालार्पितगलः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "शुनीमन्वेति श्वा हतमपि च हन्त्येव मदनः ॥ १८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "विषयाणामधिकारमाह ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भिक्षाशनं तदपि नीरसमेकवारं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "शय्या च भूः परिजनो निजदेहमात्रम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "वस्त्रं च जीर्णशतखण्डमलीनकन्था",
          "end": "line"
        },
        {
          "n": 4,
          "text": "हाहा तथापि विषया न परित्यजन्ति ॥ १९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "apparatus_entry",
      "lines": [
